#!/usr/bin/env node
// Superfluid ABI Resolver
// Self-contained — no npm install required. Imports JSON ABIs from the @sfpro/sdk
// package at runtime.
//
// Usage:
//   bunx -p @sfpro/sdk bun abi.mjs <contract>                 Full JSON ABI for a contract
//   bunx -p @sfpro/sdk bun abi.mjs <contract> <function>      Single function/event/error fragment
//   bunx -p @sfpro/sdk bun abi.mjs list                       List all available contracts
//
// Output: JSON to stdout. Errors to stderr.

// Contract name → SDK module + export name.
// Module "main" = @sfpro/sdk/abi, others = @sfpro/sdk/abi/<module>.
const ABI_MAP = {
  // @sfpro/sdk/abi (main)
  CFAv1Forwarder:                 { module: "main",       export: "cfaForwarderAbi" },
  GDAv1Forwarder:                 { module: "main",       export: "gdaForwarderAbi" },
  SuperfluidPool:                 { module: "main",       export: "gdaPoolAbi" },
  SuperToken:                     { module: "main",       export: "superTokenAbi" },
  // @sfpro/sdk/abi/core
  Superfluid:                     { module: "core",       export: "hostAbi" },
  ConstantFlowAgreementV1:        { module: "core",       export: "cfaAbi" },
  GeneralDistributionAgreementV1: { module: "core",       export: "gdaAbi" },
  InstantDistributionAgreementV1: { module: "core",       export: "idaAbi" },
  SuperTokenFactory:              { module: "core",       export: "superTokenFactoryAbi" },
  BatchLiquidator:                { module: "core",       export: "batchLiquidatorAbi" },
  TOGA:                           { module: "core",       export: "togaAbi" },
  Governance:                     { module: "core",       export: "governanceAbi" },
  // @sfpro/sdk/abi/automation
  AutoWrapManager:                { module: "automation",  export: "autoWrapManagerAbi" },
  AutoWrapStrategy:               { module: "automation",  export: "autoWrapStrategyAbi" },
  FlowScheduler:                  { module: "automation",  export: "flowSchedulerAbi" },
  VestingSchedulerV3:             { module: "automation",  export: "vestingSchedulerV3Abi" },
  // @sfpro/sdk/abi/sup
  Fontaine:                       { module: "sup",         export: "fontaineAbi" },
  FluidLocker:                    { module: "sup",         export: "lockerAbi" },
  FluidLockerFactory:             { module: "sup",         export: "lockerFactoryAbi" },
  FluidEPProgramManager:          { module: "sup",         export: "programManagerAbi" },
  StakingRewardController:        { module: "sup",         export: "stakingRewardControllerAbi" },
  SUPToken:                       { module: "sup",         export: "supTokenAbi" },
  SUPVestingFactory:              { module: "sup",         export: "vestingFactoryAbi" },
};

// Shorthand aliases → canonical name.
const ALIASES = {
  cfaforwarder: "CFAv1Forwarder",
  gdaforwarder: "GDAv1Forwarder",
  pool: "SuperfluidPool",
  gdapool: "SuperfluidPool",
  supertoken: "SuperToken",
  token: "SuperToken",
  host: "Superfluid",
  cfa: "ConstantFlowAgreementV1",
  gda: "GeneralDistributionAgreementV1",
  ida: "InstantDistributionAgreementV1",
  supertokenfactory: "SuperTokenFactory",
  factory: "SuperTokenFactory",
  batchliquidator: "BatchLiquidator",
  liquidator: "BatchLiquidator",
  toga: "TOGA",
  governance: "Governance",
  autowrapmanager: "AutoWrapManager",
  autowrap: "AutoWrapManager",
  autowrapstrategy: "AutoWrapStrategy",
  flowscheduler: "FlowScheduler",
  vestingschedulerv3: "VestingSchedulerV3",
  vestingscheduler: "VestingSchedulerV3",
  vesting: "VestingSchedulerV3",
  fontaine: "Fontaine",
  locker: "FluidLocker",
  fluidlocker: "FluidLocker",
  lockerfactory: "FluidLockerFactory",
  fluidlockerfactory: "FluidLockerFactory",
  programmanager: "FluidEPProgramManager",
  fluidepprogrammanager: "FluidEPProgramManager",
  stakingrewardcontroller: "StakingRewardController",
  staking: "StakingRewardController",
  suptoken: "SUPToken",
  sup: "SUPToken",
  supvestingfactory: "SUPVestingFactory",
  vestingfactory: "SUPVestingFactory",
};

function resolveContract(query) {
  // Exact match on canonical name (case-insensitive).
  const byCanonical = Object.keys(ABI_MAP).find(k => k.toLowerCase() === query.toLowerCase());
  if (byCanonical) return byCanonical;
  // Alias match.
  return ALIASES[query.toLowerCase()] ?? null;
}

async function loadModule(module) {
  return import(sdkImportPath(module));
}

function sdkImportPath(module) {
  return module === "main" ? "@sfpro/sdk/abi" : `@sfpro/sdk/abi/${module}`;
}

const out = o => console.log(JSON.stringify(o, null, 2));
const [command, ...args] = process.argv.slice(2);

switch (command) {
  case "list": {
    const entries = Object.entries(ABI_MAP).map(([name, { module, export: exp }]) => ({
      contract: name,
      sdkImport: sdkImportPath(module),
      sdkExport: exp,
    }));
    out(entries);
    break;
  }

  case undefined:
  case "help":
  case "--help":
  case "-h": {
    console.error(`Superfluid ABI Resolver — imports JSON ABIs from @sfpro/sdk

Commands:
  <contract>               Full JSON ABI for a contract
  <contract> <function>    Single function/event/error fragment by name
  list                     List all available contracts with SDK import info

Contracts:
  ${Object.keys(ABI_MAP).join(", ")}

Aliases:
  cfa, gda, ida, host, pool, token, factory, toga, autowrap, vesting, liquidator, ...

Examples:
  bunx -p @sfpro/sdk bun abi.mjs CFAv1Forwarder
  bunx -p @sfpro/sdk bun abi.mjs cfa
  bunx -p @sfpro/sdk bun abi.mjs SuperToken transfer
  bunx -p @sfpro/sdk bun abi.mjs list`);
    process.exit(0);
    break;
  }

  default: {
    const name = resolveContract(command);
    if (!name) {
      // Check if it's a known contract not in the SDK.
      const notInSdk = ["CFASuperAppBase", "SuperTokenV1Library"];
      const match = notInSdk.find(n => n.toLowerCase() === command.toLowerCase());
      if (match) {
        console.error(`Error: ${match} is not available in @sfpro/sdk (${match === "CFASuperAppBase" ? "abstract base contract" : "Solidity library"}).`);
        console.error(`Refer to the Rich ABI YAML: references/contracts/${match}.abi.yaml`);
      } else {
        console.error(`Error: Unknown contract "${command}".`);
        console.error(`Run "bunx -p @sfpro/sdk bun abi.mjs list" to see available contracts.`);
      }
      process.exit(1);
    }

    const entry = ABI_MAP[name];
    const mod = await loadModule(entry.module);
    const abi = mod[entry.export];

    if (!abi) {
      console.error(`Error: Export "${entry.export}" not found in SDK module "${entry.module}".`);
      process.exit(1);
    }

    const fnName = args[0];
    if (fnName) {
      const fragments = abi.filter(item => item.name?.toLowerCase() === fnName.toLowerCase());
      if (!fragments.length) {
        console.error(`Error: No ABI entry named "${fnName}" in ${name}.`);
        console.error(`Hint: Names are case-insensitive. The ABI has ${abi.filter(i => i.name).map(i => i.name).filter((v, i, a) => a.indexOf(v) === i).length} named entries.`);
        process.exit(1);
      }
      out(fragments.length === 1 ? fragments[0] : fragments);
    } else {
      out({ contract: name, sdkImport: sdkImportPath(entry.module), sdkExport: entry.export, abi });
    }
    break;
  }
}

#!/usr/bin/env node
// Superfluid Super Token Balance Resolver
// Self-contained — no npm install required. Resolves token symbols via
// @superfluid-finance/tokenlist, then queries the Super API for real-time balances.
//
// Usage:
//   bunx -p @superfluid-finance/tokenlist bun balance.mjs balance <chain-id> <token-symbol-or-address> <account>
//
// Output: JSON to stdout. Errors to stderr.

import { extendedSuperTokenList } from "@superfluid-finance/tokenlist";

const API_URL = "https://superapi.kazpi.com/super-token-balance";
const tokens = extendedSuperTokenList.tokens;

function resolveToken(chainId, symbolOrAddress) {
  const query = symbolOrAddress.toLowerCase();
  const chainTokens = tokens.filter(t => t.chainId === chainId);
  const byAddr = chainTokens.find(t => t.tags?.includes("supertoken") && t.address.toLowerCase() === query);
  if (byAddr) return byAddr;
  const bySym = chainTokens.find(t => t.tags?.includes("supertoken") && t.symbol.toLowerCase() === query);
  if (bySym) return bySym;
  return null;
}

async function fetchBalance(chain, token, account) {
  const params = new URLSearchParams({ chain: String(chain), token, account });
  const url = `${API_URL}?${params}`;
  const res = await fetch(url);
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    console.error(`Error: Super API returned HTTP ${res.status}${body ? ` — ${body}` : ""}`);
    console.error(`URL: ${url}`);
    process.exit(1);
  }
  return res.json();
}

function formatBalance(wei, decimals = 18) {
  if (wei == null) return null;
  const num = Number(wei) / 10 ** decimals;
  return { wei, formatted: num.toFixed(decimals > 8 ? 8 : decimals) };
}

function formatFlowRate(weiPerSecond, decimals = 18) {
  if (!weiPerSecond || weiPerSecond === "0") return null;
  const sign = weiPerSecond.startsWith("-") ? "-" : "";
  const abs = weiPerSecond.replace("-", "");
  const perSecond = Number(abs) / 10 ** decimals;
  const perMonth = perSecond * 2592000; // 30 days
  return {
    wei_per_second: weiPerSecond,
    tokens_per_second: `${sign}${perSecond.toFixed(decimals > 8 ? 8 : decimals)}`,
    tokens_per_month: `${sign}${perMonth.toFixed(4)}`,
  };
}

function formatTimestamp(ts) {
  if (!ts) return null;
  const n = Number(ts);
  return { unix: ts, iso: new Date(n * 1000).toISOString() };
}

const out = o => console.log(JSON.stringify(o, null, 2));
const [command, ...args] = process.argv.slice(2);

switch (command) {
  case "balance": {
    if (!args[0] || !args[1] || !args[2]) {
      console.error("Usage: balance.mjs balance <chain-id> <token-symbol-or-address> <account>");
      process.exit(1);
    }
    const chainId = Number(args[0]);
    if (isNaN(chainId)) { console.error("Error: chain-id must be a number"); process.exit(1); }

    let tokenAddress = args[1];
    let tokenMeta = null;

    if (!args[1].startsWith("0x")) {
      const resolved = resolveToken(chainId, args[1]);
      if (!resolved) {
        console.error(`Error: No Super Token found on chain ${chainId} matching "${args[1]}"`);
        console.error(`Hint: Use "bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-chain ${chainId} --super" to see available tokens.`);
        process.exit(1);
      }
      tokenAddress = resolved.address;
      tokenMeta = resolved;
    } else {
      tokenMeta = resolveToken(chainId, args[1]);
    }

    const account = args[2];
    const data = await fetchBalance(chainId, tokenAddress, account);

    const superTokenDecimals = tokenMeta?.decimals ?? 18;
    const underlyingDecimals = data.underlyingToken?.decimals ?? null;

    const result = {
      chain: data.chain,
      account: data.account,
      superToken: {
        address: data.token,
        ...(tokenMeta ? { symbol: tokenMeta.symbol, name: tokenMeta.name, decimals: tokenMeta.decimals } : {}),
        ...(tokenMeta?.extensions?.superTokenInfo ? { type: tokenMeta.extensions.superTokenInfo.type } : {}),
      },
      balance: {
        connected: formatBalance(data.connectedBalance, superTokenDecimals),
        unconnected: formatBalance(data.unconnectedBalance, superTokenDecimals),
      },
      netFlow: formatFlowRate(data.connectedNetFlow, superTokenDecimals),
      timestamp: formatTimestamp(data.timestamp),
      maybeCriticalAt: formatTimestamp(data.maybeCriticalAt),
      underlyingToken: data.underlyingToken ? {
        address: data.underlyingToken.address,
        ...(underlyingDecimals != null ? { decimals: underlyingDecimals } : {}),
        balance: formatBalance(data.underlyingToken.balance, underlyingDecimals ?? 18),
      } : null,
    };

    out(result);
    break;
  }

  default:
    console.error(`Superfluid Super Token Balance Resolver

Commands:
  balance <chain-id> <token-symbol-or-address> <account>   Get real-time Super Token balance

Examples:
  bunx -p @superfluid-finance/tokenlist bun balance.mjs balance 8453 USDCx 0xYourAddress
  bunx -p @superfluid-finance/tokenlist bun balance.mjs balance 10 0x1efF3Dd78F4A14aBfa9Fa66579bD3Ce9E1B30529 0xYourAddress`);
    process.exit(command ? 1 : 0);
}

#!/usr/bin/env node
// Superfluid Protocol Metadata Resolver
// Self-contained — no npm install required. Uses @superfluid-finance/metadata
// package for network data.
//
// Usage:
//   bunx -p @superfluid-finance/metadata bun metadata.mjs networks              # List all networks (summary)
//   bunx -p @superfluid-finance/metadata bun metadata.mjs networks --mainnets   # Only mainnets
//   bunx -p @superfluid-finance/metadata bun metadata.mjs networks --testnets   # Only testnets
//   bunx -p @superfluid-finance/metadata bun metadata.mjs network <chain-id-or-name>
//   bunx -p @superfluid-finance/metadata bun metadata.mjs contracts <chain-id-or-name>
//   bunx -p @superfluid-finance/metadata bun metadata.mjs contract <chain-id-or-name> <key>
//   bunx -p @superfluid-finance/metadata bun metadata.mjs subgraph <chain-id-or-name>
//   bunx -p @superfluid-finance/metadata bun metadata.mjs automation <chain-id-or-name>
//
// Output: JSON to stdout. Errors to stderr.

import metadata from "@superfluid-finance/metadata";
const { networks } = metadata;

function resolveNetwork(idOrName) {
  const asNum = Number(idOrName);
  if (!isNaN(asNum)) return metadata.getNetworkByChainId(asNum);
  return metadata.getNetworkByName(idOrName) || metadata.getNetworkByShortName(idOrName);
}

function requireNetwork(idOrName) {
  const network = resolveNetwork(idOrName);
  if (!network) {
    console.error(`Error: Network not found for "${idOrName}".`);
    console.error(`Available: ${networks.map(n => `${n.name} (${n.chainId})`).join(", ")}`);
    process.exit(1);
  }
  return network;
}

function summary(n) {
  return { name: n.name, chainId: n.chainId, humanReadableName: n.humanReadableName, isTestnet: n.isTestnet, nativeTokenSymbol: n.nativeTokenSymbol };
}

const out = o => console.log(JSON.stringify(o, null, 2));
const [command, ...args] = process.argv.slice(2);

switch (command) {
  case "networks": {
    const flag = args[0];
    let list = networks;
    if (flag === "--mainnets") list = networks.filter(n => !n.isTestnet);
    else if (flag === "--testnets") list = networks.filter(n => n.isTestnet);
    out(list.map(summary));
    break;
  }

  case "network": {
    if (!args[0]) { console.error("Usage: metadata.mjs network <chain-id-or-name>"); process.exit(1); }
    out(requireNetwork(args[0]));
    break;
  }

  case "contracts": {
    if (!args[0]) { console.error("Usage: metadata.mjs contracts <chain-id-or-name>"); process.exit(1); }
    const n = requireNetwork(args[0]);
    out({ network: n.name, chainId: n.chainId, nativeTokenWrapper: n.nativeTokenWrapper, ...n.contractsV1 });
    break;
  }

  case "contract": {
    if (!args[0] || !args[1]) { console.error("Usage: metadata.mjs contract <chain-id-or-name> <key>"); process.exit(1); }
    const n = requireNetwork(args[0]);
    const key = args[1];
    const addr = n.contractsV1?.[key] || (key === "nativeTokenWrapper" ? n.nativeTokenWrapper : undefined);
    if (!addr) {
      console.error(`Error: Key "${key}" not found. Available: ${Object.keys(n.contractsV1).join(", ")}, nativeTokenWrapper`);
      process.exit(1);
    }
    out({ network: n.name, chainId: n.chainId, [key]: addr });
    break;
  }

  case "subgraph": {
    if (!args[0]) { console.error("Usage: metadata.mjs subgraph <chain-id-or-name>"); process.exit(1); }
    const n = requireNetwork(args[0]);
    out({
      network: n.name, chainId: n.chainId,
      protocol: `https://subgraph-endpoints.superfluid.dev/${n.name}/protocol-v1`,
      subgraphV1: n.subgraphV1 || null,
    });
    break;
  }

  case "automation": {
    if (!args[0]) { console.error("Usage: metadata.mjs automation <chain-id-or-name>"); process.exit(1); }
    const n = requireNetwork(args[0]);
    out({
      network: n.name, chainId: n.chainId,
      vestingScheduler: n.contractsV1?.vestingScheduler || null,
      flowScheduler: n.contractsV1?.flowScheduler || null,
      autowrap: n.autowrap || null,
      subgraphs: {
        vestingScheduler: `https://subgraph-endpoints.superfluid.dev/${n.name}/vesting-scheduler`,
        flowScheduler: `https://subgraph-endpoints.superfluid.dev/${n.name}/flow-scheduler`,
        autoWrap: `https://subgraph-endpoints.superfluid.dev/${n.name}/auto-wrap`,
      },
    });
    break;
  }

  default:
    console.error(`Superfluid Metadata Resolver

Commands:
  networks [--mainnets|--testnets]     List all networks (summary)
  network <chain-id-or-name>           Full metadata for a network
  contracts <chain-id-or-name>         All contract addresses
  contract <chain-id-or-name> <key>    Single contract address
  subgraph <chain-id-or-name>          Subgraph endpoint info
  automation <chain-id-or-name>        Automation contracts + subgraphs

Examples:
  bunx -p @superfluid-finance/metadata bun metadata.mjs networks --mainnets
  bunx -p @superfluid-finance/metadata bun metadata.mjs contracts 10
  bunx -p @superfluid-finance/metadata bun metadata.mjs contract optimism-mainnet host
  bunx -p @superfluid-finance/metadata bun metadata.mjs automation base-mainnet`);
    process.exit(command ? 1 : 0);
}

#!/usr/bin/env node
// Superfluid Selector Generator
// Computes function selectors (4-byte), error selectors (4-byte), and event
// topic0 hashes (32-byte) from @sfpro/sdk ABIs.
//
// Usage:
//   bunx -p @sfpro/sdk -p js-sha3 bun selectors.mjs <contract>   One contract
//   bunx -p @sfpro/sdk -p js-sha3 bun selectors.mjs all           All contracts (YAML to stdout)
//   bunx -p @sfpro/sdk -p js-sha3 bun selectors.mjs list          List available contracts
//
// Output: YAML-formatted selectors to stdout. Errors to stderr.

import { keccak256 } from "js-sha3";

// Contract name → SDK module + export name (same as abi.mjs).
const ABI_MAP = {
  CFAv1Forwarder:                 { module: "main",       export: "cfaForwarderAbi" },
  GDAv1Forwarder:                 { module: "main",       export: "gdaForwarderAbi" },
  SuperfluidPool:                 { module: "main",       export: "gdaPoolAbi" },
  SuperToken:                     { module: "main",       export: "superTokenAbi" },
  Superfluid:                     { module: "core",       export: "hostAbi" },
  ConstantFlowAgreementV1:        { module: "core",       export: "cfaAbi" },
  GeneralDistributionAgreementV1: { module: "core",       export: "gdaAbi" },
  InstantDistributionAgreementV1: { module: "core",       export: "idaAbi" },
  SuperTokenFactory:              { module: "core",       export: "superTokenFactoryAbi" },
  BatchLiquidator:                { module: "core",       export: "batchLiquidatorAbi" },
  TOGA:                           { module: "core",       export: "togaAbi" },
  Governance:                     { module: "core",       export: "governanceAbi" },
  AutoWrapManager:                { module: "automation",  export: "autoWrapManagerAbi" },
  AutoWrapStrategy:               { module: "automation",  export: "autoWrapStrategyAbi" },
  FlowScheduler:                  { module: "automation",  export: "flowSchedulerAbi" },
  VestingSchedulerV3:             { module: "automation",  export: "vestingSchedulerV3Abi" },
  Fontaine:                       { module: "sup",         export: "fontaineAbi" },
  FluidLocker:                    { module: "sup",         export: "lockerAbi" },
  FluidLockerFactory:             { module: "sup",         export: "lockerFactoryAbi" },
  FluidEPProgramManager:          { module: "sup",         export: "programManagerAbi" },
  StakingRewardController:        { module: "sup",         export: "stakingRewardControllerAbi" },
  SUPToken:                       { module: "sup",         export: "supTokenAbi" },
  SUPVestingFactory:              { module: "sup",         export: "vestingFactoryAbi" },
};

const ALIASES = {
  cfaforwarder: "CFAv1Forwarder", gdaforwarder: "GDAv1Forwarder",
  pool: "SuperfluidPool", supertoken: "SuperToken", token: "SuperToken",
  host: "Superfluid", cfa: "ConstantFlowAgreementV1",
  gda: "GeneralDistributionAgreementV1", ida: "InstantDistributionAgreementV1",
  factory: "SuperTokenFactory", toga: "TOGA", governance: "Governance",
  autowrap: "AutoWrapManager", vesting: "VestingSchedulerV3",
  locker: "FluidLocker", fontaine: "Fontaine", staking: "StakingRewardController",
  sup: "SUPToken",
};

// -- ABI signature helpers --

function formatType(input) {
  // Use the canonical `type` field from the ABI JSON.
  // For tuple types, recursively build the tuple signature.
  if (input.type === "tuple" || input.type === "tuple[]") {
    const inner = input.components.map(formatType).join(",");
    return input.type === "tuple[]" ? `(${inner})[]` : `(${inner})`;
  }
  return input.type;
}

function signature(item) {
  const params = (item.inputs || []).map(formatType).join(",");
  return `${item.name}(${params})`;
}

function selector4(sig) {
  return "0x" + keccak256(sig).slice(0, 8);
}

function topic0(sig) {
  return "0x" + keccak256(sig);
}

// -- YAML formatting --

function padTo(str, width) {
  return str.length >= width ? str + " " : str + " ".repeat(width - str.length);
}

function formatYaml(contractName, abi) {
  const functions = abi.filter(i => i.type === "function").sort((a, b) => a.name.localeCompare(b.name));
  const events = abi.filter(i => i.type === "event").sort((a, b) => a.name.localeCompare(b.name));
  const errors = abi.filter(i => i.type === "error").sort((a, b) => a.name.localeCompare(b.name));

  const lines = [`# ${contractName} selectors — computed from @sfpro/sdk ABI`];

  if (functions.length) {
    lines.push("", "functions:");
    const entries = functions.map(f => {
      const sig = signature(f);
      return { sig, hex: selector4(sig) };
    });
    const maxSig = Math.max(...entries.map(e => e.sig.length));
    const padWidth = Math.min(maxSig + 2, 60);
    for (const { sig, hex } of entries) {
      lines.push(`  ${padTo(sig + ":", padWidth)}${hex}`);
    }
  }

  if (events.length) {
    lines.push("", "events:");
    const entries = events.map(e => {
      const sig = signature(e);
      return { sig, hex: topic0(sig) };
    });
    const maxSig = Math.max(...entries.map(e => e.sig.length));
    const padWidth = Math.min(maxSig + 2, 60);
    for (const { sig, hex } of entries) {
      lines.push(`  ${padTo(sig + ":", padWidth)}${hex}`);
    }
  }

  if (errors.length) {
    lines.push("", "errors:");
    const entries = errors.map(e => {
      const sig = signature(e);
      return { sig, hex: selector4(sig) };
    });
    const maxSig = Math.max(...entries.map(e => e.sig.length));
    const padWidth = Math.min(maxSig + 2, 60);
    for (const { sig, hex } of entries) {
      lines.push(`  ${padTo(sig + ":", padWidth)}${hex}`);
    }
  }

  lines.push("");
  return lines.join("\n");
}

// -- Module loading --

function sdkImportPath(module) {
  return module === "main" ? "@sfpro/sdk/abi" : `@sfpro/sdk/abi/${module}`;
}

async function loadAbi(name) {
  const entry = ABI_MAP[name];
  const mod = await import(sdkImportPath(entry.module));
  const abi = mod[entry.export];
  if (!abi) throw new Error(`Export "${entry.export}" not found in ${sdkImportPath(entry.module)}`);
  return abi;
}

function resolveContract(query) {
  const byCanonical = Object.keys(ABI_MAP).find(k => k.toLowerCase() === query.toLowerCase());
  if (byCanonical) return byCanonical;
  return ALIASES[query.toLowerCase()] ?? null;
}

// -- Contracts with ABI YAMLs but not in @sfpro/sdk --
// These have their ABI signatures hardcoded here.

const NON_SDK_ABIS = {
  CFASuperAppBase: [
    { type: "error", name: "UnauthorizedHost", inputs: [] },
    { type: "error", name: "NotImplemented", inputs: [] },
    { type: "error", name: "NotAcceptedSuperToken", inputs: [] },
  ],
  SuperTokenV1Library: [], // Solidity library — no selectors (all calls go through the token)
};

// -- File writing --

import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CONTRACTS_DIR = resolve(__dirname, "../references/contracts");

// -- Main --

const [command] = process.argv.slice(2);

switch (command) {
  case "list": {
    for (const name of Object.keys(ABI_MAP)) console.log(name);
    for (const name of Object.keys(NON_SDK_ABIS)) console.log(name + " (non-SDK)");
    break;
  }

  case "all": {
    for (const name of Object.keys(ABI_MAP)) {
      const abi = await loadAbi(name);
      console.log(formatYaml(name, abi));
    }
    for (const [name, abi] of Object.entries(NON_SDK_ABIS)) {
      if (abi.length) console.log(formatYaml(name, abi));
    }
    break;
  }

  case "generate": {
    // Write .selectors.yaml files to the contracts directory.
    let count = 0;
    for (const name of Object.keys(ABI_MAP)) {
      const abi = await loadAbi(name);
      const yaml = formatYaml(name, abi);
      const path = resolve(CONTRACTS_DIR, `${name}.selectors.yaml`);
      writeFileSync(path, yaml);
      console.log(`  wrote ${name}.selectors.yaml`);
      count++;
    }
    for (const [name, abi] of Object.entries(NON_SDK_ABIS)) {
      if (!abi.length) {
        console.log(`  skip ${name} (no selectors)`);
        continue;
      }
      const yaml = formatYaml(name, abi);
      const path = resolve(CONTRACTS_DIR, `${name}.selectors.yaml`);
      writeFileSync(path, yaml);
      console.log(`  wrote ${name}.selectors.yaml`);
      count++;
    }
    console.log(`\nGenerated ${count} .selectors.yaml files in references/contracts/`);
    break;
  }

  case undefined:
  case "help":
  case "--help":
  case "-h": {
    console.error(`Superfluid Selector Generator — computes selectors from @sfpro/sdk ABIs

Commands:
  <contract>    Show selectors for one contract (YAML format)
  all           Show selectors for all contracts (stdout)
  generate      Write .selectors.yaml files to references/contracts/
  list          List available contract names

Examples:
  bunx -p @sfpro/sdk -p js-sha3 bun selectors.mjs SuperToken
  bunx -p @sfpro/sdk -p js-sha3 bun selectors.mjs cfa
  bunx -p @sfpro/sdk -p js-sha3 bun selectors.mjs generate`);
    process.exit(0);
    break;
  }

  default: {
    const name = resolveContract(command);
    if (!name) {
      // Check non-SDK contracts.
      const nonSdk = Object.keys(NON_SDK_ABIS).find(k => k.toLowerCase() === command.toLowerCase());
      if (nonSdk) {
        const abi = NON_SDK_ABIS[nonSdk];
        if (abi.length) {
          console.log(formatYaml(nonSdk, abi));
        } else {
          console.error(`${nonSdk} has no selectors (Solidity library).`);
        }
        break;
      }
      console.error(`Error: Unknown contract "${command}".`);
      console.error(`Run "selectors.mjs list" to see available contracts.`);
      process.exit(1);
    }
    const abi = await loadAbi(name);
    console.log(formatYaml(name, abi));
    break;
  }
}

#!/usr/bin/env node
// Superfluid Token List Resolver
// Self-contained — no npm install required. Uses @superfluid-finance/tokenlist
// package for token data.
//
// Usage:
//   bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-address <address>
//   bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-chain <chain-id> [--super|--underlying]
//   bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-symbol <symbol> [--chain-id <chain-id>]
//   bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs super-token <chain-id> <symbol-or-address>
//   bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs stats
//
// Output: JSON to stdout. Errors to stderr.

import { extendedSuperTokenList } from "@superfluid-finance/tokenlist";

const tokens = extendedSuperTokenList.tokens;

function isSuperToken(t) { return t.tags?.includes("supertoken"); }
function isUnderlying(t) { return t.tags?.includes("underlying"); }

function tokenSummary(t) {
  const r = { chainId: t.chainId, address: t.address, name: t.name, symbol: t.symbol, decimals: t.decimals, tags: t.tags || [] };
  if (t.extensions?.superTokenInfo) r.superTokenInfo = t.extensions.superTokenInfo;
  return r;
}

const out = o => console.log(JSON.stringify(o, null, 2));
const [command, ...args] = process.argv.slice(2);

switch (command) {
  case "by-address": {
    if (!args[0]) { console.error("Usage: tokenlist.mjs by-address <address>"); process.exit(1); }
    const addr = args[0].toLowerCase();
    const matches = tokens.filter(t => t.address.toLowerCase() === addr);
    if (!matches.length) { console.error(`No token found with address ${args[0]}`); process.exit(1); }
    out(matches.map(tokenSummary));
    break;
  }

  case "by-chain": {
    if (!args[0]) { console.error("Usage: tokenlist.mjs by-chain <chain-id> [--super|--underlying]"); process.exit(1); }
    const chainId = Number(args[0]);
    if (isNaN(chainId)) { console.error("Error: chain-id must be a number"); process.exit(1); }
    let matches = tokens.filter(t => t.chainId === chainId);
    if (args[1] === "--super") matches = matches.filter(isSuperToken);
    else if (args[1] === "--underlying") matches = matches.filter(isUnderlying);
    if (!matches.length) { console.error(`No tokens found on chain ${chainId}${args[1] ? ` with filter ${args[1]}` : ""}`); process.exit(1); }
    out(matches.map(tokenSummary));
    break;
  }

  case "by-symbol": {
    if (!args[0]) { console.error("Usage: tokenlist.mjs by-symbol <symbol> [--chain-id <id>]"); process.exit(1); }
    const sym = args[0].toLowerCase();
    let matches = tokens.filter(t => t.symbol.toLowerCase() === sym);
    const ci = args.indexOf("--chain-id");
    if (ci !== -1 && args[ci + 1]) matches = matches.filter(t => t.chainId === Number(args[ci + 1]));
    if (!matches.length) { console.error(`No token found with symbol "${args[0]}"`); process.exit(1); }
    out(matches.map(tokenSummary));
    break;
  }

  case "super-token": {
    if (!args[0] || !args[1]) { console.error("Usage: tokenlist.mjs super-token <chain-id> <symbol-or-address>"); process.exit(1); }
    const chainId = Number(args[0]);
    const query = args[1].toLowerCase();
    if (isNaN(chainId)) { console.error("Error: chain-id must be a number"); process.exit(1); }
    const chainTokens = tokens.filter(t => t.chainId === chainId);
    const st = chainTokens.find(t => isSuperToken(t) && (t.symbol.toLowerCase() === query || t.address.toLowerCase() === query));
    if (!st) { console.error(`No Super Token found on chain ${chainId} matching "${args[1]}"`); process.exit(1); }
    const result = { superToken: tokenSummary(st), underlying: null };
    const ua = st.extensions?.superTokenInfo?.underlyingTokenAddress;
    if (ua) {
      const u = chainTokens.find(t => t.address.toLowerCase() === ua.toLowerCase());
      result.underlying = u ? tokenSummary(u) : { address: ua, note: "Not in token list" };
    }
    out(result);
    break;
  }

  case "stats": {
    const chains = [...new Set(tokens.map(t => t.chainId))].sort((a, b) => a - b);
    out({
      totalTokens: tokens.length,
      superTokens: tokens.filter(isSuperToken).length,
      underlyingTokens: tokens.filter(isUnderlying).length,
      chains: chains.map(id => {
        const ct = tokens.filter(t => t.chainId === id);
        return { chainId: id, total: ct.length, superTokens: ct.filter(isSuperToken).length, underlying: ct.filter(isUnderlying).length };
      }),
    });
    break;
  }

  default:
    console.error(`Superfluid Token List Resolver

Commands:
  by-address <address>                         Find token(s) by contract address
  by-chain <chain-id> [--super|--underlying]   List tokens on a network
  by-symbol <symbol> [--chain-id <id>]         Find token(s) by symbol
  super-token <chain-id> <symbol-or-address>   Find Super Token + its underlying
  stats                                        Summary stats of the token list

Examples:
  bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-address 0x4ac8bD1bDaE47beeF2D1c6Aa62229509b962Aa0d
  bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-chain 10 --super
  bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs by-symbol USDCx --chain-id 10
  bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs super-token 10 USDCx
  bunx -p @superfluid-finance/tokenlist bun tokenlist.mjs stats`);
    process.exit(command ? 1 : 0);
}
